// Three probes of the home page, a second apart; WordPress only answers its own host name, so send it.
const probes = [];
for (let i = 0; i < 3; i++) {
  if (i) await new Promise(r => setTimeout(r, 1000));
  const t = Date.now();
  try {
    const r = await this.helpers.httpRequest({ url: 'http://host.docker.internal:8092/', headers: { Host: 'localhost:8092' },
      returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 15000 });
    probes.push({ code: r.statusCode, ms: Date.now() - t });
  } catch (e) { probes.push({ code: 0, ms: Date.now() - t }); }
}
const up = probes.filter(p => p.code === 200);
return [{ json: { uptime: { ok: up.length === probes.length, checks: probes.length, up: up.length,
  avg_ms: up.length ? Math.round(up.reduce((s, p) => s + p.ms, 0) / up.length) : null,
  max_ms: up.length ? Math.max(...up.map(p => p.ms)) : null, codes: probes.map(p => p.code) } } }];

const h = $('Health').first().json, l = $('Lighthouse').first().json;
const health = h.wp_version ? h : { error: 'health endpoint unreachable' };
const lighthouse = Number.isFinite(l.score) ? { score: l.score, scale: 100, lcp_ms: l.lcp_ms, lcp_s: Math.round(l.lcp_ms / 100) / 10,
  total_bytes: l.total_bytes, total_kb: Math.round(l.total_bytes / 1024), total_mb: Math.round(l.total_bytes / 104857.6) / 10 } : null;
const now = new Date();
const backup_age_days = health.last_backup_at ? Math.floor((now - new Date(health.last_backup_at)) / 864e5) : null;
const outdated = (health.plugins || []).filter(p => p.update);
const data = { site: 'Bayview Dental (http://localhost:8092)', checked_on: now.toLocaleDateString('en-CA', { timeZone: 'Asia/Manila' }),
  period_days: 7, uptime: $('Uptime x3').first().json.uptime, health, backup_age_days, backup_max_age_days: 7,
  updates_pending: outdated.length + (health.theme_updates || 0) + (health.core_update ? 1 : 0), lighthouse };
const prompt = [
  'You write the weekly website care report for the owner of Bayview Dental, a dental clinic in Davao City. She is not technical:',
  'plain English, short sentences, no jargon (say "speed score", not "LCP"; "add-ons", not only "plugins"), calm and specific.',
  'Return ONLY JSON: {"status":"green"|"amber"|"red","headline":string (max 20 words),',
  ' "sections":[{"title":string,"body":string (1-3 sentences)}] (3-5 sections: Online and speed, Updates, Backups, Errors, Security as relevant),',
  ' "actions":[{"what":string,"why":string,"effort":"quick"|"medium"|"large"}] (1-4, most important first; if nothing is needed, one action saying so)}',
  'status: green = healthy; amber = something needs doing this week (a pending update, no backup in the last backup_max_age_days days, PHP errors, speed score under 50); red = site down or the check failed.',
  'uptime is 3 checks made just now, not monitoring over the week: never claim the site was up "all week".',
  'NUMBERS RULE: use only numbers that appear in DATA, written exactly as there (you may use lcp_s, total_kb, total_mb, avg_ms). Never compute, round, estimate or add numbers or dates of your own. If unsure, leave the number out.',
  'DATA: ' + JSON.stringify(data),
].join('\n');
return [{ json: { prompt, data } }];

// Turns Claude's reply into a safe care report. Embedded verbatim in workflow.json's "Parse" node; tested by parse.check.mjs.
// text: bridge reply (or undefined if the bridge failed), data: the run's real check data (the only source of numbers).
function parseReport(text, data) {
  const rank = { green: 0, amber: 1, red: 2 };
  const h = data.health || {};
  const outdated = (h.plugins || []).filter(p => p.update);
  const updates = outdated.length + (h.theme_updates || 0) + (h.core_update ? 1 : 0);
  const noBackup = data.backup_age_days == null || data.backup_age_days > data.backup_max_age_days;
  // The data sets a floor Claude can raise but never lower: down/unreadable = red; updates, no recent backup, errors, slow = amber.
  const floor = (!data.uptime.ok || !h.wp_version) ? 'red'
    : (updates || noBackup || h.debug_errors_24h || !data.lighthouse || data.lighthouse.score < 50) ? 'amber' : 'green';

  // Numbers guard: every number in the report must appear in the data (1,234 → 1234; 07 → 7), else that text is replaced.
  const nums = s => (String(s).replace(/(\d),(?=\d{3}\b)/g, '$1').match(/\d+(?:\.\d+)*/g) || []).map(n => n.replace(/^0+(?=\d)/, ''));
  const allowed = new Set(nums(JSON.stringify(data)));
  let guarded = 0;
  const str = (v, max) => (typeof v === 'string' && v.trim()) ? v.trim().slice(0, max) : '';
  const checked = s => { if (!s || nums(s).every(n => allowed.has(n))) return s; guarded++; return ''; };

  let r = {};
  try {
    if (typeof text !== 'string') throw new Error('bridge failed');
    const t = text.replace(/```(?:json)?/g, '');
    r = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)) || {};
  } catch (e) { r = {}; }

  const status = rank[r.status] >= rank[floor] ? r.status : floor;
  const headline = checked(str(r.headline, 160)) || {
    green: 'Your website is healthy this week — nothing needs your attention.',
    amber: 'Your website is up, but a few things need attention this week.',
    red: 'Your website needs urgent attention.' }[status];
  let sections = (Array.isArray(r.sections) ? r.sections : []).slice(0, 6).map(s => ({
    title: checked(str(s && s.title, 60)) || 'This week',
    body: checked(str(s && s.body, 700)) || 'We checked this; the exact figures are in the table below.',
  }));
  if (!sections.length) sections = [{ title: 'This week', body: 'The written summary is not available this week; the exact figures are in the table below.' }];
  const actions = (Array.isArray(r.actions) ? r.actions : []).slice(0, 5).map(a => ({
    what: checked(str(a && a.what, 160)), why: checked(str(a && a.why, 300)),
    effort: ['quick', 'medium', 'large'].includes(a && a.effort) ? a.effort : 'medium',
  })).filter(a => a.what && a.why);

  // Belt and braces: the things the data says must be done always reach the owner, even if the write-up missed them.
  const has = re => actions.some(a => re.test(a.what + ' ' + a.why));
  if (!data.uptime.ok && !has(/offline|down|online/i))
    actions.unshift({ what: 'Get the website back online', why: 'Patients could not open the site during this check.', effort: 'quick' });
  if (updates && !has(/updat/i))
    actions.push({ what: 'Install the pending updates' + (outdated.length ? ' (' + outdated.map(p => p.slug).join(', ') + ')' : ''),
      why: 'Updates close security holes; out-of-date plugins are the most common way small sites get broken into.', effort: 'quick' });
  if (noBackup && !has(/backup/i))
    actions.push({ what: 'Take a fresh backup and keep the weekly backup running', why: 'There is no recent backup, so a broken update or a hack could not be undone.', effort: 'quick' });
  if (!actions.length) actions.push({ what: 'No action needed — keep the weekly checks running', why: 'Everything we checked is healthy.', effort: 'quick' });
  return { status, headline, sections, actions, guarded };
}

return [{ json: parseReport($input.first().json.text, $('Build prompt').first().json.data) }];

const p = $('Parse').first().json, d = $('Build prompt').first().json.data, id = $('Save').first().json.id;
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const color = { green: '#1f8a4c', amber: '#b7791f', red: '#c53030' }[p.status];
const h = d.health || {}, l = d.lighthouse;
const rows = [
  ['Online', d.uptime.up + ' of ' + d.uptime.checks + ' checks' + (d.uptime.avg_ms != null ? ', average ' + d.uptime.avg_ms + ' ms' : '')],
  ['Speed score (mobile)', l ? l.score + ' / 100, main image in ' + l.lcp_s + ' s, page ' + l.total_kb + ' KB' : 'not measured'],
  ['Updates waiting', d.updates_pending + ((h.plugins || []).filter(x => x.update).map(x => ' — ' + x.slug + ' ' + x.version + ' → ' + x.update).join(''))],
  ['Last backup', d.backup_age_days == null ? 'none found' : d.backup_age_days === 0 ? 'today' : d.backup_age_days + ' days ago'],
  ['PHP errors (24 h)', h.debug_errors_24h ?? 'unknown'],
  ['WordPress / PHP', (h.wp_version || '?') + ' / ' + (h.php_version || '?')],
];
const html = '<div style="font-family:Arial,Helvetica,sans-serif;max-width:620px;margin:0 auto;color:#1a202c;line-height:1.5">'
  + '<p style="margin:0 0 4px;color:#4a5568;font-size:13px">Bayview Dental · Website care report · ' + esc(d.checked_on) + '</p>'
  + '<p style="display:inline-block;margin:8px 0;padding:4px 12px;border-radius:999px;background:' + color + ';color:#fff;font-weight:bold;font-size:13px;letter-spacing:.05em">' + p.status.toUpperCase() + '</p>'
  + '<h1 style="font-size:22px;margin:4px 0 16px">' + esc(p.headline) + '</h1>'
  + p.sections.map(s => '<h2 style="font-size:16px;margin:16px 0 4px">' + esc(s.title) + '</h2><p style="margin:0">' + esc(s.body) + '</p>').join('')
  + '<h2 style="font-size:16px;margin:24px 0 8px">What to do</h2><ol style="padding-left:20px;margin:0">'
  + p.actions.map(a => '<li style="margin-bottom:8px"><b>' + esc(a.what) + '</b> <span style="color:#4a5568;font-size:12px">(' + esc(a.effort) + ')</span><br>' + esc(a.why) + '</li>').join('') + '</ol>'
  + '<h2 style="font-size:16px;margin:24px 0 8px">The numbers</h2><table style="border-collapse:collapse;width:100%;font-size:14px">'
  + rows.map(r => '<tr><td style="padding:6px 8px;border-top:1px solid #e2e8f0;color:#4a5568">' + esc(r[0]) + '</td><td style="padding:6px 8px;border-top:1px solid #e2e8f0">' + esc(r[1]) + '</td></tr>').join('')
  + '</table><p style="margin-top:24px;color:#718096;font-size:12px">Report #' + id + '. Checked automatically every Monday 08:00; written with AI, every number checked against the data above.</p></div>';
return [{ json: { subject: 'Website care report — Bayview Dental — ' + d.checked_on + ' — ' + p.status.toUpperCase(), html } }];
